async ({ shell: { exec, execFile } }) => {
  await exec(`set -e
gh pr merge 88 --squash
git switch -q main && git pull -q
git switch -c chore/release-2.5.4 main
npm version 2.5.4 --no-git-tag-version
git commit -q -am "chore: release 2.5.4"
git push -q -u origin chore/release-2.5.4`, { timeoutMs: 240000, raise: true });
  const url = (await execFile("gh", ["pr", "create", "--base", "main", "--head", "chore/release-2.5.4", "--title", "chore: release 2.5.4", "--body", `Refs #85.

## Release notes

### Fixed
- **Git specs in \`extensions\` install with npm 12** (#85, fixed in #88). npm 12 refuses git specs, such as \`github:cv/pit#v0.37.0\`, by default. pi-action now runs \`npm install\` with \`--allow-git=root\`, so npm installs the git specs that you give, but not git dependencies of their packages. You can remove an \`NPM_CONFIG_ALLOW_GIT\` workaround from your workflow. If you set \`NPM_CONFIG_ALLOW_GIT\`, pi-action uses your value. See [Installation](https://github.com/cv/pi-action/blob/v2.5.4/docs/extensions.md#installation).
`])).stdout.trim();
  await new Promise(r => setTimeout(r, 30000));
  const c = (await exec(`gh pr checks chore/release-2.5.4 --watch --interval 15 2>&1 | tail -3`, { timeoutMs: 220000 })).stdout;
  return { url, c };
}
